    assert.equal(await projectList(), restoredListing);
    const renameTask = (title, taskId = taskIds[1], projectId = ids[0], filter = 'All') =>
      fetch(`${base}/projects/${projectId}/tasks/${taskId}/rename`, {
        method: 'POST', body: new URLSearchParams({ title, filter }), redirect: 'manual',
      });
    for (const row of rows(await taskPage())) {
      assert.match(row, /<label for="new-task-title-\d+">New task title<\/label>/);
      assert.match(row, /<button type="submit">Rename task<\/button>/);
    }
    assert.equal((await renameTask('Wrong project', taskIds[1], ids[1])).status, 404);
    assert.equal((await renameTask('Missing task', '999999')).status, 404);
    assert.equal((await renameTask('Missing project', taskIds[1], '999999')).status, 404);
    for (const title of ['', ' \t\n ']) {
      const response = await renameTask(title, taskIds[1], ids[0], 'Completed');
      assert.equal(response.status, 422);
      const html = await response.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.equal(rows(html).length, 1);
      assert.match(html, /<option selected>Completed<\/option>/);
      assert.equal(await taskPage(), restoredRenamedPage);
      assert.equal(await projectList(), restoredListing);
    }
    const taskRename = await renameTask('  Renamed <task & "title">  ', taskIds[1], ids[0], 'Completed');
    assert.equal(taskRename.status, 303);
    assert.equal(taskRename.headers.get('location'), `/projects/${ids[0]}?filter=Completed`);
    const taskRenamedPage = await taskPage();
    const taskRenamedRows = rows(taskRenamedPage);
    assert.equal(taskRenamedRows[0], rows(restoredRenamedPage)[0]);
    assert.match(taskRenamedRows[1], /<span>Renamed &lt;task &amp; &quot;title&quot;&gt;<\/span>/);
    assert.match(taskRenamedRows[1], /aria-label="Complete Renamed &lt;task &amp; &quot;title&quot;&gt;" checked/);
    assert.match(taskRenamedRows[1], /value="Renamed &lt;task &amp; &quot;title&quot;&gt;"/);
    assert.match(taskRenamedRows[1], new RegExp(`/tasks/${taskIds[1]}/rename`));
    assert.deepEqual(rows(await taskPage(ids[0], 'Completed')), [taskRenamedRows[1].replaceAll('name="filter" value="All"', 'name="filter" value="Completed"')]);
    assert.equal(rows(await taskPage(ids[0], 'Open')).length, 1);
    assert.equal(await taskPage(ids[1]), savedOtherTasks);
    assert.equal(await projectList(), restoredListing);
    assert.equal((await renameTask(' Renamed open task ', taskIds[0])).status, 303);
    assert.match(rows(await taskPage(ids[0], 'Open'))[0], /aria-label="Complete Renamed open task"/);
    assert.doesNotMatch(rows(await taskPage())[0], / checked/);
    const bothRenamedPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), bothRenamedPage);
    assert.equal(await projectList(), restoredListing);
    assert.equal((await archive('archive')).status, 303);
    const archivedTasksPage = await taskPage();
    for (const row of rows(archivedTasksPage)) {
      assert.match(row, /id="new-task-title-\d+"[^>]* disabled/);
      assert.match(row, /<button type="submit" disabled>Rename task<\/button>/);
    }
    assert.equal((await renameTask('Forbidden')).status, 403);
    assert.equal(await taskPage(), archivedTasksPage);
    await stop();
    base = await start();
    assert.equal(await taskPage(), archivedTasksPage);
    assert.equal((await archive('restore')).status, 303);
    assert.equal(await taskPage(), bothRenamedPage);
    assert.equal(await projectList(), restoredListing);
    assert.equal((await renameTask(' Restored task ')).status, 303);
    assert.match(rows(await taskPage())[1], /aria-label="Complete Restored task" checked/);
    const finalPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), finalPage);
    assert.equal(await projectList(), restoredListing);
    const priority = (value, taskId = taskIds[0], projectId = ids[0], filter = 'All') =>
      fetch(`${base}/projects/${projectId}/tasks/${taskId}/priority`, {
        method: 'POST', body: new URLSearchParams({ priority: value, filter }), redirect: 'manual',
      });
    const selectedPriority = (row) => row.match(/<select id="task-priority-\d+"[\s\S]*?<\/select>/)[0];
    for (const row of rows(finalPage)) {
      assert.match(row, /<label for="task-priority-\d+">Task priority<\/label>/);
      assert.match(selectedPriority(row), /<option>Low<\/option><option selected>Normal<\/option><option>High<\/option>/);
      assert.doesNotMatch(selectedPriority(row), /disabled/);
    }
    assert.equal((await priority('High', taskIds[0], ids[1])).status, 404);
    assert.equal((await priority('High', '999999')).status, 404);
    assert.equal((await priority('High', taskIds[0], '999999')).status, 404);
    for (const value of ['', 'Urgent', 'high']) assert.equal((await priority(value)).status, 422);
    assert.equal(await taskPage(), finalPage);
    const changed = await priority('High', taskIds[0], ids[0], 'Open');
    assert.equal(changed.status, 303);
    assert.equal(changed.headers.get('location'), `/projects/${ids[0]}?filter=Open`);
    const highRows = rows(await taskPage());
    assert.equal(highRows[0], rows(finalPage)[0].replace('<option selected>Normal</option><option>High</option>', '<option>Normal</option><option selected>High</option>'));
    assert.equal(highRows[1], rows(finalPage)[1]);
    assert.equal(await taskPage(ids[1]), savedOtherTasks);
    assert.equal(await projectList(), restoredListing);
    assert.equal(rows(await taskPage(ids[0], 'Open')).length, 1);
    assert.equal(rows(await taskPage(ids[0], 'Completed')).length, 1);
    assert.equal((await priority('Low', taskIds[1])).status, 303);
    assert.match(selectedPriority(rows(await taskPage())[0]), /<option selected>High/);
    assert.match(selectedPriority(rows(await taskPage())[1]), /<option selected>Low/);
    assert.equal((await renameTask(' Priority preserved ')).status, 303);
    assert.match(rows(await taskPage())[1], /aria-label="Complete Priority preserved" checked/);
    assert.match(selectedPriority(rows(await taskPage())[1]), /<option selected>Low/);
    const prioritiesPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), prioritiesPage);
    assert.equal(await projectList(), restoredListing);
    assert.equal((await archive('archive')).status, 303);
    const archivedPrioritiesPage = await taskPage();
    for (const row of rows(archivedPrioritiesPage)) assert.match(selectedPriority(row), / disabled/);
    assert.equal((await priority('Normal')).status, 403);
    assert.equal((await priority('High', taskIds[1])).status, 403);
    assert.equal(await taskPage(), archivedPrioritiesPage);
    await stop();
    base = await start();
    assert.equal(await taskPage(), archivedPrioritiesPage);
    assert.equal((await archive('restore')).status, 303);
    assert.equal(await taskPage(), prioritiesPage);
    assert.equal((await priority('Normal')).status, 303);
    assert.match(selectedPriority(rows(await taskPage())[0]), /<option selected>Normal/);
    assert.match(selectedPriority(rows(await taskPage())[1]), /<option selected>Low/);
    assert.equal((await createTask('New normal task')).status, 303);
    const newRows = rows(await taskPage());
    assert.equal(newRows.length, 3);
    assert.match(selectedPriority(newRows[2]), /<option selected>Normal/);
    assert.doesNotMatch(newRows[2], / checked/);
    assert.match(await projectList(), /data-testid="project-summary">1\/3 completed/);
    const finalPrioritiesPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), finalPrioritiesPage);

    // Exercise every intersection with tasks in distinct priority/completion states.
    await priority('High', taskIds[0]);
    const combinedPage = (filter = 'All', priorityFilter = 'All') => fetch(
      `${base}/projects/${ids[0]}?${new URLSearchParams({ filter, priorityFilter })}`,
    ).then((response) => response.text());
    const visibleTitles = (html) => rows(html).map((row) => row.match(/<span>(.*?)<\/span>/)[1]);
    const expectedTasks = [
      { title: 'Renamed open task', completed: false, priority: 'High' },
      { title: 'Priority preserved', completed: true, priority: 'Low' },
      { title: 'New normal task', completed: false, priority: 'Normal' },
    ];
    const assertFilters = (html, filter, priorityFilter) => {
      const filterForm = html.match(/<form[^>]*class="filter-form">[\s\S]*?<\/form>/)[0];
      for (const [id, value] of [['task-filter', filter], ['priority-filter', priorityFilter]]) {
        const select = filterForm.match(new RegExp(`<select id="${id}"[\\s\\S]*?</select>`))[0];
        assert.match(select, new RegExp(`<option selected>${value}</option>`));
        assert.doesNotMatch(select, /disabled/);
      }
    };
    const defaultPage = await taskPage();
    assertFilters(defaultPage, 'All', 'All');
    assert.match(defaultPage, /<label for="priority-filter">Priority filter<\/label>/);
    assert.match(defaultPage, /<option selected>All<\/option><option>Low<\/option><option>Normal<\/option><option>High<\/option>/);
    const summaryBeforeFilters = await projectList();
    for (const filter of ['All', 'Open', 'Completed']) {
      for (const priorityFilter of ['All', 'Low', 'Normal', 'High']) {
        const html = await combinedPage(filter, priorityFilter);
        assertFilters(html, filter, priorityFilter);
        for (const row of rows(html)) {
          for (const form of row.matchAll(/<form[\s\S]*?<\/form>/g)) {
            assert.match(form[0], new RegExp(`name="filter" value="${filter}"`));
            assert.match(form[0], new RegExp(`name="priorityFilter" value="${priorityFilter}"`));
          }
        }
        assert.deepEqual(visibleTitles(html), expectedTasks.filter((task) =>
          (filter === 'All' || task.completed === (filter === 'Completed')) &&
          (priorityFilter === 'All' || task.priority === priorityFilter),
        ).map((task) => task.title));
      }
    }
    assert.equal(await projectList(), summaryBeforeFilters);
    const editWithFilters = (action, taskId, values, filter, priorityFilter) => fetch(
      `${base}/projects/${ids[0]}/tasks/${taskId}/${action}`, {
        method: 'POST', redirect: 'manual',
        body: new URLSearchParams({ ...values, filter, priorityFilter }),
      });
    const followEdit = async (action, taskId, values, filter, priorityFilter, status = 303) => {
      const response = await editWithFilters(action, taskId, values, filter, priorityFilter);
      assert.equal(response.status, status);
      const html = status === 303
        ? await (await fetch(new URL(response.headers.get('location'), base))).text()
        : await response.text();
      assertFilters(html, filter, priorityFilter);
      return html;
    };
    let filtered = await followEdit('rename', taskIds[0], { title: '  Filtered task  ' }, 'Open', 'High');
    assert.deepEqual(visibleTitles(filtered), ['Filtered task']);
    assert.match(filtered, /aria-label="Complete Filtered task"/);
    assert.match(selectedPriority(rows(filtered)[0]), /<option selected>High/);
    assert.equal(await projectList(), summaryBeforeFilters);
    filtered = await followEdit('rename', taskIds[0], { title: '   ' }, 'Open', 'High', 422);
    assert.match(filtered, /role="alert">Task title is required/);
    assert.deepEqual(visibleTitles(filtered), ['Filtered task']);
    filtered = await followEdit('priority', taskIds[0], { priority: 'Invalid' }, 'Open', 'High', 422);
    assert.deepEqual(visibleTitles(filtered), ['Filtered task']);
    filtered = await followEdit('priority', taskIds[0], { priority: 'Low' }, 'Open', 'High');
    assert.deepEqual(visibleTitles(filtered), []);
    assert.deepEqual(visibleTitles(await combinedPage('Open', 'Low')), ['Filtered task']);
    assert.equal(await projectList(), summaryBeforeFilters);
    filtered = await followEdit('completion', taskIds[0], { completed: '1' }, 'Open', 'Low');
    assert.deepEqual(visibleTitles(filtered), []);
    assert.deepEqual(visibleTitles(await combinedPage('Completed', 'Low')), ['Filtered task', 'Priority preserved']);
    filtered = await followEdit('completion', taskIds[0], {}, 'Completed', 'Low');
    assert.deepEqual(visibleTitles(filtered), ['Priority preserved']);
    assert.equal(await projectList(), summaryBeforeFilters);
    const savedCombinedPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), savedCombinedPage);
    assert.deepEqual(visibleTitles(await combinedPage('Open', 'Low')), ['Filtered task']);
    assert.equal(await projectList(), summaryBeforeFilters);
    await archive('archive');
    const archivedCombinedPage = await combinedPage('Completed', 'Low');
    assertFilters(archivedCombinedPage, 'Completed', 'Low');
    assert.deepEqual(visibleTitles(archivedCombinedPage), ['Priority preserved']);
    assert.match(archivedCombinedPage, /Archived project/);
    for (const row of rows(archivedCombinedPage)) {
      assert.match(row, /type="checkbox"[\s\S]*?disabled/);
      assert.match(row, /id="new-task-title-\d+"[^>]* disabled/);
      assert.match(row, /<button type="submit" disabled>Rename task/);
      assert.match(selectedPriority(row), /disabled/);
    }
    await followEdit('priority', taskIds[1], { priority: 'High' }, 'Completed', 'Low', 403);
    await stop();
    base = await start();
    assert.equal(await combinedPage('Completed', 'Low'), archivedCombinedPage);
    await archive('restore');
    assert.equal(await taskPage(), savedCombinedPage);
    assert.equal(await projectList(), summaryBeforeFilters);

    // Defaults affect only future tasks in their own project, preserving filters and all existing data.
    const defaultSelect = (html) => html.match(/<select id="default-task-priority"[\s\S]*?<\/select>/)[0];
    const setDefault = (value, projectId = ids[0], filter = 'Open', priorityFilter = 'Low') => fetch(
      `${base}/projects/${projectId}/default-priority`, {
        method: 'POST', redirect: 'manual',
        body: new URLSearchParams({ priority: value, filter, priorityFilter }),
      });
    assert.match(await taskPage(), /<label for="default-task-priority">Default task priority<\/label>/);
    assert.match(defaultSelect(await taskPage()), /<option>Low<\/option><option selected>Normal<\/option><option>High<\/option>/);
    assert.equal((await setDefault('High', '999999')).status, 404);
    for (const value of ['', 'Urgent', 'high']) assert.equal((await setDefault(value)).status, 422);
    assert.equal(await taskPage(), savedCombinedPage);
    const beforeDefaultRows = rows(await combinedPage('Open', 'Low'));
    const changedDefault = await setDefault('High');
    assert.equal(changedDefault.status, 303);
    assert.equal(changedDefault.headers.get('location'), `/projects/${ids[0]}?filter=Open&priorityFilter=Low`);
    const defaultChangedPage = await (await fetch(new URL(changedDefault.headers.get('location'), base))).text();
    assertFilters(defaultChangedPage, 'Open', 'Low');
    assert.deepEqual(rows(defaultChangedPage), beforeDefaultRows);
    assert.deepEqual(rows(await taskPage()), rows(savedCombinedPage));
    assert.equal(await projectList(), summaryBeforeFilters);
    assert.equal(await taskPage(ids[1]), savedOtherTasks);
    assert.match(defaultSelect(defaultChangedPage), /<option selected>High/);
    await stop();
    base = await start();
    assert.match(defaultSelect(await taskPage()), /<option selected>High/);
    await createTask('Inherited high');
    let inheritedRows = rows(await taskPage());
    assert.match(selectedPriority(inheritedRows[3]), /<option selected>High/);
    assert.match(inheritedRows[3], /<span>Inherited high<\/span>/);
    assert.doesNotMatch(inheritedRows[3], / checked/);
    const inheritedId = inheritedRows[3].match(/\/tasks\/(\d+)\/completion/)[1];
    await setDefault('Low');
    assert.deepEqual(rows(await taskPage()), inheritedRows);
    await createTask('Inherited low');
    inheritedRows = rows(await taskPage());
    assert.match(selectedPriority(inheritedRows[3]), /<option selected>High/);
    assert.match(selectedPriority(inheritedRows[4]), /<option selected>Low/);
    await setDefault('High', ids[1]);
    assert.match(defaultSelect(await taskPage()), /<option selected>Low/);
    assert.match(defaultSelect(await taskPage(ids[1])), /<option selected>High/);
    await createTask('Other inherited high', ids[1]);
    assert.match(selectedPriority(rows(await taskPage(ids[1]))[1]), /<option selected>High/);
    await rename('Default preserved');
    await renameTask('Inherited renamed', inheritedId);
    assert.match(defaultSelect(await taskPage()), /<option selected>Low/);
    assert.match(selectedPriority(rows(await taskPage())[3]), /<option selected>High/);
    const defaultsSavedPage = await taskPage();
    const defaultsSavedList = await projectList();
    assert.match(defaultsSavedList, /data-testid="project-summary">1\/5 completed/);
    await archive('archive');
    const archivedDefaultPage = await combinedPage('Open', 'Low');
    assertFilters(archivedDefaultPage, 'Open', 'Low');
    assert.match(defaultSelect(archivedDefaultPage), /disabled/);
    assert.match(defaultSelect(archivedDefaultPage), /<option selected>Low/);
    assert.equal((await setDefault('Normal')).status, 403);
    assert.equal(await combinedPage('Open', 'Low'), archivedDefaultPage);
    await stop();
    base = await start();
    assert.equal(await combinedPage('Open', 'Low'), archivedDefaultPage);
    assert.match(defaultSelect(await taskPage(ids[1])), /<option selected>High/);
    await archive('restore');
    assert.equal(await taskPage(), defaultsSavedPage);
    assert.equal(await projectList(), defaultsSavedList);
    assert.doesNotMatch(defaultSelect(await taskPage()), /disabled/);
    await createTask('Restored inherited low');
    assert.match(selectedPriority(rows(await taskPage())[5]), /<option selected>Low/);
    await setDefault('Normal');
    await createTask('Inherited normal again');
    assert.match(selectedPriority(rows(await taskPage())[6]), /<option selected>Normal/);
    const finalDefaultsPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), finalDefaultsPage);

    // Calendar validation, clearing, independence, filters, archive, and persistence.
    const dueInput = (row) => row.match(/<input id="task-due-date-\d+"[^>]*>/)[0];
    const withoutDueForm = (row) => row.replace(/\s*<form[^>]*class="create-form task-due-date-form">[\s\S]*?<\/form>/, '');
    const dueBeforeRows = rows(await taskPage());
    const dueBeforeList = await projectList();
    const dueOtherPage = await taskPage(ids[1]);
    for (const row of dueBeforeRows) {
      assert.match(row, /<label for="task-due-date-\d+">Task due date<\/label>/);
      assert.match(dueInput(row), /type="text" value=""/);
      assert.match(row, /<button type="submit">Save due date<\/button>/);
    }
    for (const value of [' 2024-02-29 ', '0001-01-01', '9999-12-31', '2000-02-29', '2400-02-29', '2025-04-30']) {
      const edited = await followEdit('due-date', taskIds[0], { dueDate: value }, 'Open', 'Low');
      assert.match(dueInput(rows(edited)[0]), new RegExp(`value="${value.trim()}"`));
    }
    const validDuePage = await taskPage();
    for (const value of ['0000-01-01', '10000-01-01', '1900-02-29', '2100-02-29', '2025-02-29',
      '2024-02-30', '2025-04-31', '2025-00-01', '2025-13-01', '2025-01-00', '2025-1-01',
      '25-01-01', '2025/01/01', '2025-01-01T00:00:00Z', '<invalid>']) {
      const edited = await followEdit('due-date', taskIds[0], { dueDate: value }, 'Open', 'Low', 422);
      assert.match(edited, /role="alert">Due date must be a valid YYYY-MM-DD date/);
      assert.match(dueInput(rows(edited)[0]), /value="2025-04-30"/);
      assert.equal(await taskPage(), validDuePage);
    }
    assert.deepEqual(rows(validDuePage).map(withoutDueForm), dueBeforeRows.map(withoutDueForm));
    assert.deepEqual(rows(validDuePage).slice(1), dueBeforeRows.slice(1));
    assert.equal(await taskPage(ids[1]), dueOtherPage);
    assert.equal(await projectList(), dueBeforeList);
    assert.equal((await editWithFilters('due-date', '999999', { dueDate: '2024-01-01' }, 'All', 'All')).status, 404);
    const wrongOwner = await fetch(`${base}/projects/${ids[1]}/tasks/${taskIds[0]}/due-date`, {
      method: 'POST', redirect: 'manual', body: new URLSearchParams({ dueDate: '2024-01-01' }),
    });
    assert.equal(wrongOwner.status, 404);
    await followEdit('due-date', taskIds[1], { dueDate: '0001-12-31' }, 'Completed', 'Low');
    await followEdit('rename', taskIds[0], { title: 'Dated task renamed' }, 'Open', 'Low');
    assert.match(dueInput(rows(await taskPage())[0]), /value="2025-04-30"/);
    const savedDatesPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), savedDatesPage);
    await archive('archive');
    const archivedDatesPage = await taskPage();
    for (const row of rows(archivedDatesPage)) {
      assert.match(dueInput(row), / disabled/);
      assert.match(row, /<button type="submit" disabled>Save due date<\/button>/);
    }
    await followEdit('due-date', taskIds[0], { dueDate: '' }, 'Open', 'Low', 403);
    assert.equal(await taskPage(), archivedDatesPage);
    await stop();
    base = await start();
    assert.equal(await taskPage(), archivedDatesPage);
    await archive('restore');
    assert.equal(await taskPage(), savedDatesPage);
    for (const value of ['', ' \t\n ']) {
      await followEdit('due-date', taskIds[0], { dueDate: value }, 'Open', 'Low');
      assert.match(dueInput(rows(await taskPage())[0]), /value=""/);
      assert.match(dueInput(rows(await taskPage())[1]), /value="0001-12-31"/);
    }
    assert.equal(await projectList(), dueBeforeList);
    const clearedDatesPage = await taskPage();
    await stop();
    base = await start();
    assert.equal(await taskPage(), clearedDatesPage);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
:root { font-family: system-ui, sans-serif; color: #243245; background: #f4f6f9; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 850px; margin: 0 auto; padding: 60px 24px; }
header { margin-bottom: 32px; }
h1 { font-size: clamp(2rem, 5vw, 3rem); letter-spacing: -.04em; margin: 8px 0; overflow-wrap: anywhere; }
h2 { font-size: 1.2rem; margin: 0 0 20px; }
h3 { font-size: 1rem; margin: 0; overflow-wrap: anywhere; }
.eyebrow { color: #5364a6; font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .12em; }
.intro, .empty { color: #627086; line-height: 1.6; }
.card, .project-row { background: white; border: 1px solid #dce2eb; border-radius: 12px; padding: 24px; }
.card + .card { margin-top: 24px; }
.create-form { display: flex; gap: 16px; align-items: end; }
.field { flex: 1; min-width: 0; }
label { display: block; font-size: .9rem; font-weight: 600; margin-bottom: 8px; }
input { width: 100%; padding: 12px; border: 1px solid #acb8ca; border-radius: 6px; font: inherit; }
button { border: 1px solid #4054a3; border-radius: 6px; padding: 12px 18px; background: #4054a3; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #304387; }
.secondary { color: #354991; background: #f7f8fc; border-color: #ccd4e6; white-space: nowrap; }
.secondary:hover { background: #e8ecf6; }
input:focus-visible, button:focus-visible, select:focus-visible { outline: 3px solid #8fa5fa; outline-offset: 3px; }
.project-list { margin-top: 36px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 12px; }
.project-row > div:first-child { min-width: 0; }
.project-actions { display: flex; flex-wrap: wrap; gap: 10px; }
.summary { color: #627086; margin: 8px 0 0; }
.archive-notice { padding: 12px; background: #e8ecf6; border-radius: 6px; font-weight: 600; }
button:disabled { background: #e0e4eb; color: #627086; border-color: #ccd4e6; cursor: default; }
.task-label:has(input:disabled) { cursor: default; }
.alert { color: #962d2d; background: #fff0f0; padding: 12px; border-radius: 6px; }
.detail { margin-top: 40px; }
.filter-form { margin-bottom: 20px; }
.filter-form select + label { margin-top: 16px; }
select { padding: 10px 12px; border: 1px solid #acb8ca; border-radius: 6px; background: white; font: inherit; }
.task-row { background: white; border: 1px solid #dce2eb; border-radius: 12px; padding: 20px 24px; margin-bottom: 12px; }
