  const savedTask = (projectId, taskId) => {
    const db = new DatabaseSync(dbPath);
    try {
      const value = db.prepare('"'SELECT id, project_id, title, completed, priority, due_date FROM tasks WHERE id = ? AND project_id = ?').get(taskId, projectId);
